from itertools import islice

counts = {"source": 0, "doubled": 0, "big": 0}

def source():
    for n in range(1, 21):
        counts["source"] += 1
        yield n

def doubled(stream):
    for n in stream:
        counts["doubled"] += 1
        yield n * 2

def big(stream):
    for n in stream:
        if n > 10:
            counts["big"] += 1
            yield n

result = list(islice(big(doubled(source())), 3))
print("result:", result)
print("counts:", counts)

