from itertools import islice

def naturals_from(n):
    while True:
        yield n
        n += 1

def sieve(stream):
    prime = next(stream)
    yield prime
    yield from sieve(n for n in stream if n % prime != 0)

print("first 8 primes:", list(islice(sieve(naturals_from(2)), 8)))

