import io

def broken_reader(text):
    with io.StringIO(text) as f:
        return iter(f)

def working_reader(text):
    with io.StringIO(text) as f:
        yield from f

try:
    list(broken_reader("a\nb\nc\n"))
except ValueError as e:
    print("broken version:", type(e).__name__, "-", e)
print("working version:", [line.strip() for line in working_reader("a\nb\nc\n")])

def count_matching(items, target):
    found = 0
    for item in items:
        if item == target:
            found += 1
        yield item
    return found

gen = count_matching(["a", "b", "a", "c", "a"], "a")
collected = []
try:
    while True:
        collected.append(next(gen))
except StopIteration as stop:
    print("items passed through:", collected)
    print("the sub-generator's return value:", stop.value)

def walk(node):
    if isinstance(node, dict):
        for key, value in node.items():
            yield key
            yield from walk(value)
    elif isinstance(node, list):
        for item in node:
            yield from walk(item)
    else:
        yield node

tree = {"name": "root", "children": [{"name": "leaf-a"}, {"name": "leaf-b"}]}
print(list(walk(tree)))

def accumulator():
    total = 0
    while True:
        value = yield total
        if value is None:
            return total
        total += value

def relay():
    result = yield from accumulator()
    print("  [relay] sub-generator returned:", result)

gen = relay()
print("primed, running total:", next(gen))
print("after sending 5:", gen.send(5))
print("after sending 7:", gen.send(7))
try:
    gen.send(None)
except StopIteration:
    print("relay finished")

