class Squares:
    def __init__(self, limit):
        self._limit = limit
        self._n = 0
    def __iter__(self):
        return self
    def __next__(self):
        self._n += 1
        if self._n > self._limit:
            raise StopIteration
        return self._n * self._n

def squares_gen(limit):
    n = 0
    while n < limit:
        n += 1
        yield n * n

print("class version:    ", list(Squares(4)))
print("generator version:", list(squares_gen(4)))
s = Squares(4)
print("the class instance is one-shot:", list(s), "then", list(s))
g = squares_gen(4)
print("a generator is one-shot too:  ", list(g), "then", list(g))

