class Peekable:
    def __init__(self, iterable):
        self._it = iter(iterable)
        self._held = []
    def __iter__(self):
        return self
    def __next__(self):
        if self._held:
            return self._held.pop()
        return next(self._it)
    def peek(self):
        if not self._held:
            self._held.append(next(self._it))
        return self._held[0]

stream = Peekable([10, 20, 30])
print("peeked:", stream.peek())
print("peeked again, same item:", stream.peek())
print("now consuming:", next(stream), next(stream), next(stream))

